using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// --- Create the research agent using Microsoft Agent Framework ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic, you:
        1. Search the web multiple times to gather diverse information.
        2. Save important findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve all notes and produce a
           well-structured summary with key points and sources.
        Always search at least 3 times with different queries before summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run the agent ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

await foreach (var update in agent.RunStreamingAsync(messages, options: runOptions))
{
    Console.Write(update.Text);
}

Console.WriteLine("\n\n=== Research Complete ===");

// --- Tool implementations ---

[Description("Searches the web for information on a given query. Returns search results with titles and snippets.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration.
    // In production, integrate with Bing Search API, Google Custom Search, or similar.
    Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

    var results = query.ToLowerInvariant() switch
    {
        var q when q.Contains("quantum computing") && q.Contains("recent") =>
            """
            1. "Quantum Computing Breakthroughs in 2026" - Nature Physics
               IBM and Google have demonstrated quantum error correction at scale, achieving logical qubit error rates below 0.1%.

            2. "Microsoft's Topological Qubits Reach Milestone" - MIT Technology Review
               Microsoft announced its Majorana-based topological qubits have achieved 99.9% gate fidelity in lab conditions.

            3. "Quantum Advantage Demonstrated for Drug Discovery" - Science Daily
               A 1000-qubit system solved molecular simulation problems 10,000x faster than classical supercomputers.
            """,
        var q when q.Contains("quantum") && q.Contains("application") =>
            """
            1. "Practical Applications of Quantum Computing" - IEEE Spectrum
               Key applications include cryptography, drug discovery, financial modeling, and optimization problems.

            2. "Quantum Machine Learning: State of the Art" - arXiv
               Quantum neural networks show promise for pattern recognition in high-dimensional spaces.

            3. "Supply Chain Optimization with Quantum Annealing" - Harvard Business Review
               D-Wave systems reduce logistics costs by 15-30% for complex routing problems.
            """,
        var q when q.Contains("quantum") && q.Contains("challenge") =>
            """
            1. "The Biggest Challenges Facing Quantum Computing" - Wired
               Decoherence, error rates, and the need for extreme cooling remain major obstacles.

            2. "Quantum Workforce Shortage" - Forbes
               Industry faces a shortage of 50,000+ quantum engineers globally by 2027.

            3. "When Will Quantum Computers Be Practical?" - The Economist
               Experts estimate general-purpose quantum advantage is 5-10 years away for most industries.
            """,
        _ =>
            $"""
            1. "Overview of {query}" - Wikipedia
               A comprehensive overview covering the main aspects and current state of research.

            2. "Latest Developments in {query}" - TechCrunch
               Recent advances and industry trends related to the topic.

            3. "{query}: What Experts Say" - Scientific American
               Expert opinions and future outlook on the subject.
            """
    };

    return results;
}

var noteStore = new List<string>();

[Description("Saves a research note for later reference. Use this to record important findings.")]
string SaveNote([Description("The note content to save")] string note)
{
    noteStore.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({noteStore.Count} total)");
    return $"Note saved successfully. You now have {noteStore.Count} note(s).";
}

[Description("Retrieves all saved research notes.")]
string GetNotes()
{
    if (noteStore.Count == 0)
        return "No notes saved yet.";

    Console.WriteLine($"  [Tool] Retrieving {noteStore.Count} notes");
    return string.Join("\n---\n", noteStore.Select((n, i) => $"Note {i + 1}: {n}"));
}

